16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: a leading '+' followed by 8 to 15 digits")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    @Email
63	    private String email;
64	
65	    @Column(name = "registration_date", columnDefinition = "DATE")
66	    private LocalDate registrationDate;
67	
68	    @Column(name = "birth_date", columnDefinition = "DATE")
69	    private LocalDate birthDate;
70	
71	    @Column(name = "customer_code")
72	    private String customerCode;
73	
74	    @Column(name = "household_id")
75	    private String householdId;
76	
77	    @Column(name = "namesake_count")
78	    private Integer namesakeCount;
79	
80	    @Column(name = "household_size")
81	    private Integer householdSize;
82	
83	    @Column(name = "postcode")
84	    private String postcode;
85	
86	    @Column(name = "possible_duplicate")
87	    private Boolean possibleDuplicate;
88	
89	    @Column(name = "possible_duplicate_of")
90	    private Integer possibleDuplicateOf;
91	
92	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
93	    private Set<Pet> pets;
94	
95	    public String getTitle() {
96	        return this.title;
97	    }
98	
99	    public void setTitle(String title) {
100	        this.title = title;
101	    }
102	
103	    /**
104	     * The owner's salutation, derived from the {@link #title} and last name: {@code title + ' ' +
105	     * lastName} when a title is present, or just the last name when no title was supplied.
106	     */
107	    @Transient
108	    public String getSalutation() {
109	        if (this.title == null || this.title.isBlank()) {
110	            return getLastName();
111	        }
112	        return this.title + " " + getLastName();
113	    }
114	
115	    public String getAddress() {
116	        return this.address;
117	    }
118	
119	    public void setAddress(String address) {
120	        this.address = address;
121	    }
122	
123	    public String getAddressLine1() {
124	        return this.addressLine1;
125	    }
126	
127	    public void setAddressLine1(String addressLine1) {
128	        this.addressLine1 = addressLine1;
129	    }
130	
131	    public String getAddressLine2() {
132	        return this.addressLine2;
133	    }
134	
135	    public void setAddressLine2(String addressLine2) {
136	        this.addressLine2 = addressLine2;
137	    }
138	
139	    public String getCity() {
140	        return this.city;
141	    }
142	
143	    public void setCity(String city) {
144	        this.city = city;
145	    }
146	
147	    public String getTelephone() {
148	        return this.telephone;
149	    }
150	
151	    public void setTelephone(String telephone) {
152	        this.telephone = telephone;
153	    }
154	
155	    public String getEmail() {
156	        return this.email;
157	    }
158	
159	    /**
160	     * Stores the email lower-cased so it is persisted and returned in a canonical form. A
161	     * {@code null} value (email omitted) is preserved as {@code null}.
162	     */
163	    public void setEmail(String email) {
164	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
165	    }
166	
167	    public LocalDate getRegistrationDate() {
168	        return this.registrationDate;
169	    }
170	
171	    public void setRegistrationDate(LocalDate registrationDate) {
172	        this.registrationDate = registrationDate;
173	    }
174	
175	    public LocalDate getBirthDate() {
176	        return this.birthDate;
177	    }
178	
179	    public void setBirthDate(LocalDate birthDate) {
180	        this.birthDate = birthDate;
181	    }
182	
183	    /**
184	     * The owner's age band, derived from {@link #birthDate} measured against the
185	     * {@link #registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64
186	     * inclusive, and {@code SENIOR} at 65 or over. Returns {@code null} when no birth date was
187	     * supplied, so the field is simply absent from the response.
188	     */
189	    @Transient
190	    public String getAgeBand() {
191	        if (this.birthDate == null) {
192	            return null;
193	        }
194	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
195	        int age = java.time.Period.between(this.birthDate, reference).getYears();
196	        if (age < 18) {
197	            return "MINOR";
198	        }
199	        if (age < 65) {
200	            return "ADULT";
201	        }
202	        return "SENIOR";
203	    }
204	
205	    /** National-number length by country code, mirroring the create-time E.164 normalization. */
206	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
207	
208	    /**
209	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
210	     * national digits grouped in threes from the left (e.g. {@code +61412345678 -> +61 412 345 678}).
211	     * The country code is recognised from the known set ({@code +61} with 9 national digits, {@code +1}
212	     * with 10) that the create-time normalization produces. Values that are absent or not in E.164 form
213	     * are returned unchanged, so the raw {@link #telephone} still stands in for a display value.
214	     */
215	    @Transient
216	    public String getTelephoneDisplay() {
217	        if (this.telephone == null || !this.telephone.startsWith("+")) {
218	            return this.telephone;
219	        }
220	        String digits = this.telephone.substring(1);
221	        if (!digits.matches("[0-9]+")) {
222	            return this.telephone;
223	        }
224	        String countryCode = null;
225	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
226	            if (digits.startsWith(entry.getKey())
227	                && digits.length() - entry.getKey().length() == entry.getValue()) {
228	                countryCode = entry.getKey();
229	                break;
230	            }
231	        }
232	        if (countryCode == null) {
233	            return this.telephone;
234	        }
235	        String national = digits.substring(countryCode.length());
236	        StringBuilder grouped = new StringBuilder();
237	        for (int i = 0; i < national.length(); i += 3) {
238	            if (grouped.length() > 0) {
239	                grouped.append(' ');
240	            }
241	            grouped.append(national, i, Math.min(i + 3, national.length()));
242	        }
243	        return "+" + countryCode + " " + grouped;
244	    }
245	
246	    public String getCustomerCode() {
247	        return this.customerCode;
248	    }
249	
250	    public void setCustomerCode(String customerCode) {
251	        this.customerCode = customerCode;
252	    }
253	
254	    /**
255	     * A single Luhn check digit (0-9) computed over the digits contained in the
256	     * {@link #customerCode}. Non-digit characters in the code are ignored; the standard Luhn
257	     * algorithm doubles every second digit from the right (subtracting 9 when the result exceeds
258	     * 9) and the check digit is {@code (10 - (sum % 10)) % 10}. {@code null} until a customer code
259	     * is assigned.
260	     */
261	    @Transient
262	    public Integer getCheckDigit() {
263	        if (this.customerCode == null) {
264	            return null;
265	        }
266	        int sum = 0;
267	        boolean dbl = true;
268	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
269	            char c = this.customerCode.charAt(i);
270	            if (c < '0' || c > '9') {
271	                continue;
272	            }
273	            int d = c - '0';
274	            if (dbl) {
275	                d *= 2;
276	                if (d > 9) {
277	                    d -= 9;
278	                }
279	            }
280	            sum += d;
281	            dbl = !dbl;
282	        }
283	        return (10 - (sum % 10)) % 10;
284	    }
285	
286	    /**
287	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where {@code YY} is
288	     * the last two digits of the {@code registrationDate} year (e.g. {@code NSW-1A2B3C4D-M26}).
289	     * Derived from the owner's own fields; {@code null} until both are assigned.
290	     */
291	    @Transient
292	    public String getMembershipNumber() {
293	        if (this.customerCode == null || this.registrationDate == null) {
294	            return null;
295	        }
296	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
297	    }
298	
299	    /**
300	     * The owner's membership points, derived from the owner's own fields. Points start at 0 and
301	     * accumulate: 2 when an email is present, 1 when the owner has no namesakes ({@code namesakeCount}
302	     * is 0), 2 when the owner belongs to a household of 3 or more members ({@code householdSize} is at
303	     * least 3), and 3 when the owner's tenure — whole days from {@link #registrationDate} to today —
304	     * exceeds 365. Because a newly created owner registers today and so has zero tenure, and joins a
305	     * household of at most itself unless others already share it, a new owner's points reflect only the
306	     * factors captured at creation time.
307	     */
308	    @Transient
309	    public Integer getMembershipPoints() {
310	        int points = 0;
311	        boolean hasEmail = this.email != null && !this.email.isBlank();
312	        if (hasEmail) {
313	            points += 2;
314	        }
315	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
316	        if (noNamesakes) {
317	            points += 1;
318	        }
319	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
320	        if (largeHousehold) {
321	            points += 2;
322	        }
323	        boolean longTenure = this.registrationDate != null
324	            && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
325	        if (longTenure) {
326	            points += 3;
327	        }
328	        return points;
329	    }
330	
331	    /**
332	     * The owner's membership level, a number from 1 to 4, derived from {@link #getMembershipPoints()}:
333	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more
334	     * points.
335	     */
336	    @Transient
337	    public Integer getMembershipLevel() {
338	        int points = getMembershipPoints();
339	        if (points <= 1) {
340	            return 1;
341	        }
342	        if (points <= 3) {
343	            return 2;
344	        }
345	        if (points <= 5) {
346	            return 3;
347	        }
348	        return 4;
349	    }
350	
351	    /** City -> canonical region for the {@code region} derivation. */
352	    private static final Map<String, String> CITY_REGION = Map.of(
353	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
354	
355	    /** Region -> inclusive 4-digit postcode range {low, high} for the {@code region} derivation. */
356	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
357	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
358	
359	    /** Region -> IANA timezone for the {@code timezone} derivation. */
360	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
361	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
362	
363	    /**
364	     * The region code that forms the {@code REGION} segment of the {@link #customerCode}, derived
365	     * by looking up the region by {@link #postcode} range first (NSW 2000-2099, VIC 3000-3099,
366	     * QLD 4000-4099), and only falling back to the fixed city-to-region table (Sydney->NSW,
367	     * Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no known range. Returns
368	     * {@code UNKNOWN} when neither source resolves a region.
369	     */
370	    @Transient
371	    public String getRegion() {
372	        String region = regionForPostcode(this.postcode);
373	        if (region != null) {
374	            return region;
375	        }
376	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
377	    }
378	
379	    /**
380	     * The owner's locality: the {@code REGION} segment of its {@link #customerCode} (everything
381	     * before the first {@code '-'}). Because the customer code is {@code <REGION>-<HASH8>} with
382	     * {@code REGION} derived from the postcode, the locality now simply reads that region back off
383	     * the identity. Returns {@code UNKNOWN} until a customer code is assigned.
384	     */
385	    @Transient
386	    public String getLocality() {
387	        if (this.customerCode == null) {
388	            return "UNKNOWN";
389	        }
390	        int dash = this.customerCode.indexOf('-');
391	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
392	    }
393	
394	    /**
395	     * The owner's timezone as an IANA name, derived from its {@link #getLocality() locality} (the
396	     * region) via the fixed region-to-timezone table: {@code NSW->Australia/Sydney},
397	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}. Returns {@code null} when
398	     * the locality is not one of those regions.
399	     */
400	    @Transient
401	    public String getTimezone() {
402	        return REGION_TIMEZONE.get(getLocality());
403	    }
404	
405	    /** Region whose postcode range contains the given postcode, or {@code null} when none does. */
406	    private static String regionForPostcode(String postcode) {
407	        if (postcode == null) {
408	            return null;
409	        }
410	        int value;
411	        try {
412	            value = Integer.parseInt(postcode.trim());
413	        }
414	        catch (NumberFormatException ex) {
415	            return null;
416	        }
417	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
418	            int[] range = entry.getValue();
419	            if (value >= range[0] && value <= range[1]) {
420	                return entry.getKey();
421	            }
422	        }
423	        return null;
424	    }
425	
426	    /**
427	     * The owner's identity key, the single derived value all duplicate detection is based on. It is
428	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
429	     * is the stored E.164 value, the email is the stored lower-cased value (empty when absent) and
430	     * the household segment is the deterministic {@code householdId} derived from the last name and
431	     * postcode (empty only when no household id has been assigned). Two owners are duplicates only
432	     * when their whole identity keys are equal.
433	     */
434	    @Transient
435	    public String getIdentityKey() {
436	        String telephonePart = this.telephone == null ? "" : this.telephone;
437	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
438	        String householdPart = this.householdId == null ? "" : this.householdId;
439	        return telephonePart + "|" + emailPart + "|" + householdPart;
440	    }
441	
442	    public String getHouseholdId() {
443	        return this.householdId;
444	    }
445	
446	    public void setHouseholdId(String householdId) {
447	        this.householdId = householdId;
448	    }
449	
450	    public Integer getNamesakeCount() {
451	        return this.namesakeCount;
452	    }
453	
454	    public void setNamesakeCount(Integer namesakeCount) {
455	        this.namesakeCount = namesakeCount;
456	    }
457	
458	    public Integer getHouseholdSize() {
459	        return this.householdSize;
460	    }
461	
462	    public void setHouseholdSize(Integer householdSize) {
463	        this.householdSize = householdSize;
464	    }
465	
466	    public String getPostcode() {
467	        return this.postcode;
468	    }
469	
470	    public void setPostcode(String postcode) {
471	        this.postcode = postcode;
472	    }
473	
474	    public Boolean getPossibleDuplicate() {
475	        return this.possibleDuplicate;
476	    }
477	
478	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
479	        this.possibleDuplicate = possibleDuplicate;
480	    }
481	
482	    public Integer getPossibleDuplicateOf() {
483	        return this.possibleDuplicateOf;
484	    }
485	
486	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
487	        this.possibleDuplicateOf = possibleDuplicateOf;
488	    }
489	
490	    protected Set<Pet> getPetsInternal() {
491	        if (this.pets == null) {
492	            this.pets = new HashSet<>();
493	        }
494	        return this.pets;
495	    }
496	
497	    protected void setPetsInternal(Set<Pet> pets) {
498	        this.pets = pets;
499	    }
500	
501	    public List<Pet> getPets() {
502	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
503	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
504	        return Collections.unmodifiableList(sortedPets);
505	    }
506	
507	    public void setPets(List<Pet> pets) {
508	        this.pets = new HashSet<>(pets);
509	    }
510	
511	    public void addPet(Pet pet) {
512	        getPetsInternal().add(pet);
513	        pet.setOwner(this);
514	    }
515	
516	    /**
517	     * Return the Pet with the given name, or null if none found for this Owner.
518	     *
519	     * @param name to test
520	     * @return true if pet name is already in use
521	     */
522	    public Pet getPet(String name) {
523	        return getPet(name, false);
524	    }
525	
526	    /**
527	     * Return the Pet with the given name, or null if none found for this Owner.
528	     *
529	     * @param name to test
530	     * @return true if pet name is already in use
531	     */
532	    public Pet getPet(String name, boolean ignoreNew) {
533	        name = name.toLowerCase();
534	        for (Pet pet : getPetsInternal()) {
535	            if (!ignoreNew || !pet.isNew()) {
536	                String compName = pet.getName();
537	                compName = compName.toLowerCase();
538	                if (compName.equals(name)) {
539	                    return pet;
540	                }
541	            }
542	        }
543	        return null;
544	    }
545	
546	    public Pet getPet(Integer petId) {
547	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
548	    }
549	
550	    @Override
551	    public String toString() {
552	        return new ToStringCreator(this)
553	
554	            .append("id", this.getId())
555	            .append("new", this.isNew())
556	            .append("lastName", this.getLastName())
557	            .append("firstName", this.getFirstName())
558	            .append("address", this.address)
559	            .append("city", this.city)
560	            .append("telephone", this.telephone)
561	            .append("email", this.email)
562	            .toString();
563	    }
564	}
